 const locale=()=>window.TOCRI18n?.getLocale?.()||'en',t=(key,values={})=>Object.entries(values).reduce((text,[name,value])=>text.replaceAll(`{${name}}`,typeof value==='number'?new Intl.NumberFormat(locale()).format(value):String(value)),copy[key]?.[locale()==='de'?0:locale()==='ar'?2:1]||key);
 const node=(tag,text='',className='')=>{const item=document.createElement(tag);item.textContent=text;if(className)item.className=className;return item;};
 const label=(tag,key)=>{const item=node(tag,t(key));item.dataset.searchCopy=key;return item;};
