 const marked=(text,highlights)=>{const pre=node('div','','content-search-text');pre.dir='auto';let offset=0;for(const span of highlights){pre.append(document.createTextNode(text.slice(offset,span.start)),node('mark',text.slice(span.start,span.end)));offset=span.end;}pre.append(document.createTextNode(text.slice(offset)));return pre;};
 let panel=null,toggle=null,timer=null,state=null,result=null,requestId=0,searching=false,openDialog=null;
 const api=async(path,data)=>{const response=await localRequest(`/api/search/${path}`,data);return response.json();};
