 function updateStatus(){if(!panel||!state)return;const status=panel.querySelector('.content-search-status');status.textContent=state.available===false?t('unavailable'):state.error?t('error'):[t('progress',state),state.phase==='cleaning'?t('cleaning'):state.incomplete?t('partial'):'',state.paused&&state.enabled?t('paused'):'',state.enabled?t('sourceNote',{missing:state.missingSource||0,limited:state.limited||0}):t('note')].filter(Boolean).join(' ');for(const key of ['start','pause','resume','rebuild']){const item=panel.querySelector(`[data-action="${key}"]`);item.hidden=state.available===false||(key==='start'?state.enabled:key==='pause'?!state.enabled||state.paused||state.phase==='ready':key==='resume'?!state.enabled||!state.paused:false);}}
 async function refreshStatus(){clearTimeout(timer);if(!panel||panel.hidden)return;try{state=await api('status');updateStatus();}catch{panel.querySelector('.content-search-status').textContent=t('error');}if(panel&&!panel.hidden)timer=setTimeout(()=>{if(!document.querySelector('#documents-view')?.hidden)void refreshStatus();},1500);}
 async function configure(key){try{state=await api('configure',{rebuild:key==='rebuild',paused:key==='pause',confirm:true});state.available=true;updateStatus();if(key!=='pause')void refreshStatus();}catch(error){panel.querySelector('.content-search-error').textContent=errorText(error);}}
 function renderHits(){if(!panel)return;const host=panel.querySelector('.content-search-hits');host.replaceChildren();if(!result)return;if(!result.hits.length)host.append(node('p',t('empty')));for(const hit of result.hits){const article=node('article','','content-search-hit'),name=node('h4',hit.names.join(' · '));name.dir='auto';const meta=node('p',`${t(hit.historical?'historical':'current',hit)} · ${t(hit.kind==='source'?'source':'translation')}${hit.location?` · ${t('page',hit.location)}`:''}`);article.append(name,meta,marked(hit.snippet.text,hit.snippet.highlights),button('open',()=>void showHit(hit)));host.append(article);}const next=button('next',()=>void search(true));next.hidden=!result.cursor;host.append(next);}
 async function search(more=false){if(searching)return;const form=panel.querySelector('form');if(!form.reportValidity())return;const ticket=++requestId;searching=true;panel.querySelector('.content-search-error').textContent='';const submit=panel.querySelector('[type="submit"]');submit.disabled=true;submit.textContent=t('loading');try{const query=panel.querySelector('[name="content-query"]').value,history=panel.querySelector('[name="content-history"]').checked;const response=await api('query',{query,history,cursor:more?result?.cursor:null,limit:25});if(ticket!==requestId)return;result=response;state={available:true,...response.status};updateStatus();renderHits();if(more)panel.querySelector('.content-search-hits button')?.focus();}catch(error){panel.querySelector('.content-search-error').textContent=errorText(error);}finally{searching=false;submit.disabled=false;submit.textContent=t('search');}}
 async function showHit(hit){
  const launcher=document.activeElement,dialog=node('dialog','','workspace-dialog content-search-dialog');dialog.dataset.noTranslate='';dialog.setAttribute('aria-labelledby','content-hit-title');const title=node('h2',t('loading'));title.id='content-hit-title';const header=node('div','','workspace-dialog-header'),close=button('close',()=>window.TOCRDialogs.close(dialog));header.append(title,close);const body=node('div','','workspace-dialog-body'),footer=node('div','','workspace-dialog-footer');dialog.append(header,body,footer);document.body.append(dialog);let viewer=null,closed=false;openDialog=dialog;dialog.addEventListener('close',()=>{closed=true;viewer?.destroy();dialog.remove();if(openDialog===dialog)openDialog=null;},{once:true});window.TOCRDialogs.bind(dialog);window.TOCRDialogs.open(dialog,launcher);
  try{const saved=await api('open',{token:hit.token});if(closed)return;title.textContent=saved.names.join(' · ');title.dir='auto';body.append(node('p',t(saved.historical?'historical':'current',saved)),label('p','excerpt'));const grid=node('div','','content-search-comparison'),text=node('section');text.append(node('h3',t(saved.kind==='source'?'source':'translation')),marked(saved.text,saved.highlights));grid.append(text);body.append(grid);
   if(saved.location){const source=node('section'),heading=label('h3','original'),host=node('div','','content-search-original'),message=node('p',t('page',saved.location));source.append(heading,message,host);grid.append(source);const showOriginal=button('original',async()=>{showOriginal.disabled=true;host.replaceChildren(node('p',t('loading')));try{const manifest=await localRequest(`/api/jobs/${saved.jobId}/source/manifest?original=1`).then(r=>r.json()),meta=manifest.files?.[saved.location.fileIndex];if(!meta)throw new Error('Missing original');const response=await localRequest(`/api/jobs/${saved.jobId}/source/${saved.location.fileIndex}?original=1`),bytes=new Uint8Array(await response.arrayBuffer()),rendered=await sourceCanvas({...meta,bytes},saved.location.page);if(closed)return;if(rendered.pages<saved.location.page)throw new Error('Unavailable original page');host.replaceChildren();viewer?.destroy();viewer=createSourceViewer(host);viewer.setCanvas(rendered.canvas,saved.location.box||null,{textItems:rendered.textItems});if(saved.location.box)viewer.focusRegion();}catch{if(!closed)host.replaceChildren(node('p',t('originalError')));}finally{showOriginal.disabled=false;}});source.append(showOriginal);
   }else body.append(label('p','unknown'));
   if(!saved.historical)footer.append(button('review',async()=>{try{const fresh=await api('open',{token:hit.token});window.TOCRDialogs.close(dialog);await openReviewWorkspace(fresh.jobId);if(reviewData?.version!==fresh.version){document.querySelector('#review-error').textContent=t('stale');return;}if(fresh.location)await focusField({...fresh.location,source:fresh.text.slice(fresh.highlights[0].start,fresh.highlights[0].end)},{locate:false,original:true});}catch(error){if(!closed)body.append(node('p',errorText(error)));}}));
  }catch(error){if(!closed){title.textContent=t('error');body.replaceChildren(node('p',errorText(error)));}}
 }
 function mount(toolbar){if(panel?.isConnected)return;toggle=button('toggle',()=>{panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden){panel.querySelector('input').focus();void refreshStatus();}else clearTimeout(timer);});toggle.id='library-content-toggle';toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-controls','library-content-search');toggle.dataset.noTranslate='';toolbar.append(toggle);panel=node('section','','card content-search-panel');panel.id='library-content-search';panel.dataset.noTranslate='';panel.hidden=true;panel.append(label('h3','title'),label('p','note'));const form=node('form','','content-search-form'),query=node('input');query.type='search';query.name='content-query';query.required=true;query.minLength=2;query.maxLength=160;query.id='library-content-query';query.setAttribute('aria-label',t('query'));const queryLabel=label('label','query');queryLabel.htmlFor=query.id;queryLabel.append(query);const history=node('input');history.type='checkbox';history.name='content-history';const historyLabel=label('label','history');historyLabel.className='check-label';historyLabel.prepend(history);const submit=label('button','search');submit.type='submit';form.append(queryLabel,historyLabel,submit);form.onsubmit=event=>{event.preventDefault();result=null;void search();};form.oninput=()=>{requestId++;result=null;renderHits();};panel.append(form);const status=node('p','','content-search-status');status.setAttribute('role','status');const controls=node('div','','content-search-controls');for(const key of ['start','pause','resume','rebuild']){const action=button(key,()=>void configure(key));action.dataset.action=key;controls.append(action);}const error=node('p','','content-search-error');error.setAttribute('role','alert');const hits=node('div','','content-search-hits');hits.setAttribute('aria-live','polite');panel.append(status,controls,error,hits);toolbar.after(panel);}
 window.TOCRContentSearch={mount};const toolbar=document.querySelector('#document-cards .library-toolbar');if(toolbar)mount(toolbar);
 window.addEventListener('translateocr-locale',()=>{if(!panel)return;for(const item of [toggle,...panel.querySelectorAll('[data-search-copy]')]){const key=item.dataset.searchCopy;if(item.tagName==='LABEL'){const input=item.querySelector('input');item.textContent=t(key);if(input){if(input.type==='checkbox')item.prepend(input);else item.append(input);}}else item.textContent=t(key);}panel.querySelector('[name="content-query"]').setAttribute('aria-label',t('query'));updateStatus();renderHits();if(openDialog)window.TOCRDialogs.close(openDialog);});
